import re


def title_of(html: str) -> str:
    """Return the text between the first <title> and </title> in html.

    The tags are matched case-insensitively. The text is returned as-is,
    without stripping whitespace. Returns "" when there is no complete
    <title>...</title> pair. Never touches the network.
    """
    match = re.search(r"<title>(.*?)</title>", html, re.IGNORECASE | re.DOTALL)
    if match is None:
        return ""
    return str(match.group(1))


def test_title_basic() -> None:
    assert title_of("<html><head><title>Hi</title></head></html>") == "Hi"


def test_title_missing() -> None:
    assert title_of("<html><body>no title here</body></html>") == ""


def test_title_uppercase_tags() -> None:
    assert title_of("<HTML><TITLE>X</TITLE></HTML>") == "X"


def test_title_unclosed_returns_empty() -> None:
    assert title_of("<title>X") == ""


def test_title_preserves_whitespace() -> None:
    assert title_of("<title> A </title>") == " A "
